using System;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace MDNote {public partial class MainWindow {
    void WriteGuideIcon(string name,FrameworkElement element){element.Resources.MergedDictionaries.Add(Resources);var host=new Button {Content=element,Style=(Style)Resources[typeof(Button)],Foreground=Ui.Brush("#263242"),BorderThickness=new Thickness(0),Padding=new Thickness(0),Margin=new Thickness(0),Focusable=false};host.Measure(new Size(Double.PositiveInfinity,Double.PositiveInfinity));host.Arrange(new Rect(new Point(),host.DesiredSize));host.UpdateLayout();Size size=element.RenderSize;var bitmap=new RenderTargetBitmap((int)Math.Ceiling(size.Width),(int)Math.Ceiling(size.Height),96,96,PixelFormats.Pbgra32);var backdrop=new DrawingVisual();using(var context=backdrop.RenderOpen())context.DrawRoundedRectangle(Ui.Brush("#EEF1F5"),null,new Rect(new Point(),size),2,2);bitmap.Render(backdrop);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"guide-"+name+".png")))encoder.Save(output);}
    internal void ExportGuideAssets(){int action=0;foreach(string name in new[]{"row-add","row-remove","column-add","column-remove","table-delete"})WriteGuideIcon(name,Ui.TableActionIcon(action++));WriteGuideIcon("heading",Ui.HeadingIcon(2,false));WriteGuideIcon("bullet",Ui.ListIcon(false,false));WriteGuideIcon("number",Ui.ListIcon(true,false));WriteGuideIcon("check",Ui.CheckboxIcon());WriteGuideIcon("quote",Ui.GlyphImage("❯",700,false,14));WriteGuideIcon("rule",Ui.RuleIcon());WriteGuideIcon("code",Ui.GlyphImage("</>",600,false,26));WriteGuideIcon("link",Ui.LinkIcon());WriteGuideIcon("inline",Ui.HighlighterIcon());WriteGuideIcon("image",Ui.ImageIcon());WriteGuideIcon("table",Ui.TableIcon());var color=new Grid {Width=18,Height=18};color.Children.Add(Ui.GlyphImage("A",400,false,18));color.Children.Add(new Border {Height=2,VerticalAlignment=VerticalAlignment.Bottom,Background=Brushes.Red});WriteGuideIcon("color",color);WriteGuideIcon("bold",Ui.GlyphImage("B",700,false,18));WriteGuideIcon("italic",new TextBlock {Text="A",FontFamily=new FontFamily("Segoe UI"),FontSize=15,FontStyle=FontStyles.Italic,Width=18,Height=18,TextAlignment=TextAlignment.Center,Foreground=Ui.Brush("#263242")});WriteGuideIcon("strike",Ui.StrikeIcon());foreach(string name in new[]{"new","open","save","edit","find","replace","dark"})WriteGuideIcon(name,Ui.Icon(name));WriteGuideIcon("txt",Ui.TxtIcon());WriteGuideIcon("source",Ui.CenteredInkIcon("sourceBraceA",16,0.5));WriteGuideIcon("outline",Ui.OutlineIcon());}
}}
